mapper.select:
SELECT 
  FROM sys04_role
 WHERE sys04_role_nm LIKE #{roleName}
   AND sys04_company_id = #{companyId}
 ORDER BY sys04_seq

mapper.update:
UPDATE sys04_role
   SET sys04_role_nm = #{roleNm},
       sys04_seq     = #{seq},
       sys04_note    = #{note}
 WHERE sys04_role_id    = #{roleId}
   AND sys04_company_id = #{companyId}

mapper.delete:
DELETE FROM sys04_role
 WHERE sys04_company_id = #{companyId}
   AND sys04_role_id IN
#{id}
